# Mock w3lib.encoding.resolve_encoding behavior for 'iso-8859-1'
def resolve_encoding(encoding_alias):
    # This mimics w3lib's behavior of mapping 'iso-8859-1' to 'cp1252'
    # which is the cause of the change in the test.
    if encoding_alias.lower() == 'iso-8859-1':
        return 'cp1252'
    return encoding_alias

# Mock Scrapy's Headers class to get encoding from Content-Type
class MockHeaders:
    def __init__(self, headers_dict):
        self._headers = headers_dict

    def get_encoding(self):
        content_type = self._headers.get("Content-type", [None])[0]
        if not content_type:
            return None
        try:
            _, params = content_type.split(';', 1)
            params = params.strip()
            if params.lower().startswith('charset='):
                encoding = params[len('charset='):].strip()
                if encoding.startswith(('"', "'")) and encoding.endswith((encoding[0],)):
                    encoding = encoding[1:-1]
                return resolve_encoding(encoding)
        except ValueError:
            pass
        return None

