        # In TextResponse, this checks headers then body. We simplify.
        return self.headers.get_encoding()

    def _body_inferred_encoding(self):
        return 'some_fallback' # for completeness

    @property
    def encoding(self):
        # This logic mirrors TextResponse.encoding's implementation
        return self._encoding or self._declared_encoding() or self._body_inferred_encoding()

