class Elem:
    def xpath(self, query, namespaces=None):
        # An XPath function like count() returns a float
        if query == 'count(//p)':
            return 1.0
        return []

lxml_mock = MagicMock()
lxml_mock.etree.XPathError = type('XPathError', (Exception,), {})
lxml_mock.etree.fromstring.return_value = Elem()
sys.modules['lxml'] = lxml_mock
sys.modules['lxml.etree'] = lxml_mock.etree

# Minimal implementation of Scrapy classes to prove the point
class XPathSelectorList(list):
    def xpath(self, xpath):
        # In the real implementation, this would chain calls
        return XPathSelectorList([s.select(xpath) for s in self])

class LxmlSelectorPoc:
    __class__ = None # self-referential, simplifies mocking

    def __init__(self, root=None, expr=None, namespaces=None):
        self.root = root
        self.expr = expr
        self.namespaces = namespaces

    def select(self, xpath):
        try:
            xpathev = self.root.xpath
        except AttributeError:
            # This is the problematic outcome: subsequent queries fail silently
            return XPathSelectorList([])

        try:
            result = xpathev(xpath, namespaces=self.namespaces)
        except lxml_mock.etree.XPathError:
            raise ValueError("Invalid XPath: %s" % xpath)

        if type(result) is not list:
            result = [result]

        result = [self.__class__(root=x, expr=xpath, namespaces=self.namespaces)
                  for x in result]
        return XPathSelectorList(result)

LxmlSelectorPoc.__class__ = LxmlSelectorPoc

# --- Test --- #
try:
    # 1. Initial selector on some HTML content
    selector = LxmlSelectorPoc(root=Elem())

    # 2. Select a count, which returns a float. The implementation wraps it
    #    in a selector, creating LxmlSelector(root=1.0).
    intermediate_selector_list = selector.select('count(//p)')

    # 3. Attempting to query further from the malformed selector
    final_result = intermediate_selector_list.xpath('./a')

    # 4. The call fails silently inside .select(), returning an empty list
    if isinstance(final_result, XPathSelectorList) and len(final_result) == 0:
        print("CONFIRMED")
    else:
        print("REFUTED")
except Exception:
    print("REFUTED")

