import weakref
import gc

# This object will track if cleanup methods were called.
class Tracker:
    doc_freed = False

tracker = Tracker()

# Mocks for libxml2 objects
class MockDoc:
    def freeDoc(self):
        tracker.doc_freed = True

    def xpathNewContext(self):
        return MockContext()

class MockContext:
    def xpathFreeContext(self):
        pass

# The class under review
class Libxml2Document(object):
    def __init__(self):
        self.xmlDoc = MockDoc()
        self.xpathContext = self.xmlDoc.xpathNewContext()

    def __del__(self):
        # The code from the file
        try:
            self.xmlDoc.freeDoc()
        except:
            pass
        try:
            self.xpathContext.xpathFreeContext()
        except:
            pass

def run_test():
    doc = Libxml2Document()

    # Simulate the condition described in the source code comments:
    # a method becoming None, leading to a TypeError during cleanup.
    doc.xmlDoc.freeDoc = None

    # We need to get the object garbage collected to trigger __del__.
    doc_ref = weakref.ref(doc)
    del doc
    gc.collect()

    # If __del__ failed to call freeDoc (because of the silenced TypeError),
    # tracker.doc_freed will be False, confirming a silent resource leak.
    if doc_ref() is None and not tracker.doc_freed:
        print("CONFIRMED")
    else:
        print("REFUTED")

run_test()

