import six
from scrapy.http import HtmlResponse
from scrapy.link import Link
from scrapy.linkextractors.lxmlhtml import LxmlLinkExtractor
from scrapy.selector import Selector


class HTMLImageLinkExtractor(LxmlLinkExtractor):
    def __init__(self, *args, **kwargs):
        kwargs.setdefault('tags', 'img')
        kwargs.setdefault('attrs', 'src')
        self.locations = kwargs.pop('locations', [])
        super(HTMLImageLinkExtractor, self).__init__(*args, **kwargs)

    def _iter_links(self, document):
        if self.locations:
            for location in self.locations:
                if isinstance(location, six.string_types):
                    for el in document.xpath(location):
                        for link in super(HTMLImageLinkExtractor, self)._iter_links(el):
                            yield link
                else:
                    for link in super(HTMLImageLinkExtractor, self)._iter_links(location):
                        yield link
        else:
            for link in super(HTMLImageLinkExtractor, self)._iter_links(document):
                yield link


def test_claim():
    body = b'''
    <html>
      <body>
        <div id="content">
            <img src="/img1.jpg">
        </div>
        <div id="sidebar">
            <img src="/img2.jpg">
        </div>
      </body>
    </html>
    '''
    response = HtmlResponse(url='http://example.com/page.html', body=body)

    # The intent is to extract links ONLY from the #content div
    selector_list_location = [response.xpath('//div[@id="content"]')]

    lx = HTMLImageLinkExtractor(locations=selector_list_location)
    links = lx.extract_links(response)

    # The bug is that LxmlLinkExtractor._iter_links (the super call) ignores the
    # context of the passed selector and re-scans the whole body, finding both images.
    # The expected behavior is to find only one link.
    if len(links) == 2:
        print("CONFIRMED")
    else:
        print("REFUTED")

test_claim()

