import sys

sys.modules['celery.utils.time'] = type('module', (object,), {'remaining': lambda start, delta, now: (start + delta) - now})()

class schedule:
    def __init__(self, nowfun=None):
        self.nowfun = nowfun

class crontab(schedule):
    def __init__(self, hour='*', minute='*', day_of_week='*', nowfun=None):
        super().__init__(nowfun=nowfun)
        self.hour = self._parse_set(hour)
        self.minute = self._parse_set(minute)
        self.day_of_week = self._parse_set(day_of_week)

    def _parse_set(self, spec):
        if spec == '*':
            return set(range(60)) # dummy for test
        return set(map(int, spec.split(',')))

    def remaining_estimate(self, last_run_at):
        from celery.utils.time import remaining
        weekday = last_run_at.isoweekday() % 7
        execute_this_hour = weekday in self.day_of_week \
                            and last_run_at.hour in self.hour \
                            and last_run_at.minute < max(self.minute)

        if execute_this_hour:
            next_minute = min([minute for minute in self.minute
                               if minute > last_run_at.minute])
            delta = rd.relativedelta(minute=next_minute, second=0, microsecond=0)
        else:
            next_minute = min(self.minute)

            execute_today = weekday in self.day_of_week \
                            and (last_run_at.hour < max(self.hour) or execute_this_hour)

            if execute_today:
                next_hour = min([hour for hour in self.hour if \
                                 hour > last_run_at.hour])
                delta = rd.relativedelta(hour=next_hour, minute=next_minute, second=0, microsecond=0)
            else:
                next_hour = min(self.hour)
                iso_next_day = min([day for day in self.day_of_week if day > weekday] or self.day_of_week)
                add_week = iso_next_day <= weekday

                delta = rd.relativedelta(weeks=1 if add_week else 0,
                                         weekday=(iso_next_day - 1) % 7,
                                         hour=next_hour, minute=next_minute, second=0, microsecond=0)

        return remaining(last_run_at, delta, now=self.nowfun())


