class AsyncResult:
    def __init__(self, task_id, backend=None, task_name=None, app=None, parent=None):
        # In the copy, 'app' will be the traceback string, e.g., 'fail'.
        self.app = app or Celery.current_app
        # 'backend' will be the result, which is None for a failed task.
        # This line will access self.app.backend, where self.app is a string.
        try:
            self.backend = backend or self.app.backend
        except AttributeError:
            # Python 3+ will raise an AttributeError here, as a string has no 'backend' attribute.
            # We catch it and re-raise a different exception to confirm the path.
            raise TypeError("Demonstration successful")
        self.task_id = task_id
        self._result = None
        self._state = None
        self._traceback = None

    def __reduce__(self):
        return (self.__class__, (self.task_id, self._result, self._state, self._traceback))

    # The new __copy__ method from the diff
    def __copy__(self):
        if sys.version_info.major == 2:
            # On Python 2, use built-in apply
            return apply(*self.__reduce__())
        else:
            # On Python 3, simulate apply(callable, args)
            constructor, args = self.__reduce__()
            return constructor(*args)


