def check_context_overwriting():
    app = flask.Flask(__name__)

    # This context processor provides a default value for 'key'.
    @app.context_processor
    def context_processor():
        return {'key': 'from_processor'}

    # This argument to render_template should override the context processor.
    context_from_render = {'key': 'from_render_arg'}

    # The update_template_context function modifies the dictionary in-place.
    # It's what render_template calls internally.
    with app.app_context():
        app.update_template_context(context_from_render)

    # Check if the value from the render argument has won.
    if context_from_render['key'] == 'from_render_arg':
        print("CONFIRMED")
    else:
        # This would happen if the processor's value overwrote the render argument's value.
        print("REFUTED")

