# Mock Jinja2's get_or_select_template logic to demonstrate the type confusion.
# On Python 3, `bytes` is not an instance of `str`, so it's treated as an iterable.


def get_or_select_template_mock(template_name_or_list):
    # In Jinja2, this check is for string types, which on Python 3 does not include `bytes`.
    if isinstance(template_name_or_list, str):
        if template_name_or_list == "template.html":
            return "found string"
        raise ValueError(f"Template '{template_name_or_list}' not found")

    # `bytes` will be treated as an iterable here.
    for name in template_name_or_list:
        # `name` will be an integer (the byte value), which is not a valid template name.
        # This will raise an exception in a real Jinja loader, here simulated with TypeError.
        if not isinstance(name, str):
            raise TypeError(f"Template name must be a string, got {type(name).__name__}")
    raise ValueError("No template found")


# The function under test
def render_template(template_name_or_list, **context):
    # The function directly passes its argument to the Jinja2 environment method
    return get_or_select_template_mock(template_name_or_list)


