    if sys.version_info.major < 3:
        # The bug is specific to Python 3's string/bytes distinction
        print("REFUTED")
        return

    try:
        # Calling with a bytestring on Python 3
        render_template(b"template.html")
        print("REFUTED")
    except TypeError as e:
        # The claim is that a bytestring is iterated, causing a TypeError when processing an integer as a template name.
        if "integer" in str(e) or "int" in str(e):
            print("CONFIRMED")
        else:
            print("REFUTED")
    except Exception:
