def jsonify_vulnerable(*args, **kwargs):
    padded = kwargs.pop('padded', False)
    if args and kwargs:
        raise TypeError('jsonify() behavior undefined when passed both args and kwargs')
    elif len(args) == 1:
        data = args[0]
    else:
        data = kwargs

    json_data = json.dumps(data).encode('utf-8')
    response = MockResponse(json_data, mimetype='application/json')

    if padded:
        callback_key = 'callback'
        if isinstance(padded, str):
            callback_key = padded

        # In Flask, `request` is a thread-local proxy.
        # We simulate its relevant part for this demonstration.
        callback_val = request.args.get(callback_key)

        if callback_val:
            # The vulnerability: `callback_val` is not validated or escaped.
            response.data = ('%s(%s)' % (callback_val, response.data.decode('utf-8'))).encode('utf-8')
            response.mimetype = 'application/javascript'

    return response


