import sys

class CaseInsensitiveDict(dict):
    def __init__(self, data=None, **kwargs):
        super(CaseInsensitiveDict, self).__init__()
        if data:
            self.update(data)
        if kwargs:
            self.update(kwargs)

    @property
    def lower_keys(self):
        if not hasattr(self, '_lower_keys') or not self._lower_keys:
            self._lower_keys = dict((k.lower(), k) for k in self.keys())
        return self._lower_keys

    def _clear_lower_keys(self):
        if hasattr(self, '_lower_keys'):
            self._lower_keys.clear()

    def __setitem__(self, key, value):
        dict.__setitem__(self, key, value)
        self._clear_lower_keys()

    def __delitem__(self, key):
        dict.__delitem__(self, key)
        self._lower_keys.clear()

try:
    # Instantiate with data, but don't perform any lookups.
    # The '_lower_keys' cache will not be created yet.
    d = CaseInsensitiveDict({'Key': 'Value'})

    # Attempt to delete an item. This calls the flawed __delitem__.
    del d['Key']

    # The bug did not manifest if this is reached.
