# Helper to simulate environment
def smart_str(s, *args, **kwargs):
    return str(s)

class _SkipField(Exception):
    pass

# The function under review, with new logic
def serialize_model(self, instance):
    data = {}
    fields = self.get_fields(instance)
    obj = None
    for fname in fields:
        if hasattr(self, smart_str(fname)):
            meth = getattr(self, fname)
            # In Python 2, inspect.getargspec(bound_method).args would not include 'self'.
            # So len(...)==2 means it was looking for method(self, instance) on the class.
            # We simulate this behavior for a self-contained test.
            try:
                spec = inspect.getfullargspec(meth.__func__)
                is_method_like = inspect.ismethod(meth) and len(spec.args) == 2
            except AttributeError: # Not a method
                is_method_like = False

            if is_method_like:
                obj = meth(instance)
            else: # Fallthrough for snippet clarity, original code would also fallthrough
                if hasattr(instance, '__contains__') and fname in instance:
                    obj = instance[fname]
                elif hasattr(instance, smart_str(fname)):
                    obj = getattr(instance, fname)
                else:
                    continue

        elif hasattr(instance, '__contains__') and fname in instance:
            obj = instance[fname]
        elif hasattr(instance, smart_str(fname)):
            obj = getattr(instance, fname)
        else:
            continue

        try:
            key = self.serialize_key(fname)
            val = self.serialize_val(fname, obj)
            data[key] = val
        except _SkipField:
            pass
    return data

