class FakeRequest:
    def __init__(self, method='POST', content_type='application/json', data=b''):
        self.method = method
        self.META = {'CONTENT_TYPE': content_type, 'CONTENT_LENGTH': str(len(data))}
        self._stream = BytesIO(data)
        self._read_started = False
        self._post = None

    @property
    def POST(self):
        if self._post is None:
            self._load_post_and_files()
        return self._post

    def _load_post_and_files(self):
        if self.method != 'POST':
            self._post = {}
            return
        if self.META.get('CONTENT_TYPE', '').startswith(('application/x-www-form-urlencoded', 'multipart/form-data')):
            # Simplified for brevity: proper parsing not implemented
            self._post = {}
        else:
            # This is Django's behavior for other content types
            # It consumes the request body
            body = self.read()
            # Simplified QueryDict-like behavior
            self._post = {body.decode('utf-8'): ''}

    def read(self, *args, **kwargs):
        self._read_started = True
        return self._stream.read(*args, **kwargs)

class RequestMixin:
    def __init__(self, request):
        self.request = request
        self._data = None

    @property
    def DATA(self):
        if self._data is None:
            self._data = self.parse()
        return self._data

    def get_stream(self):
        # In the old DRF version, this incorrectly returned the request object itself,
        # which has a readable stream. Accessing it consumes the stream.
        return self.request

    def parse(self):
        stream = self.get_stream()
        # Simplified JSONParser behavior
        import json
        body = stream.read()
        if not body:
            return {}
        return json.loads(body)

