class ImproperlyConfigured(Exception):
    pass

# --- Mocks based on the new structure in the diff ---

class Serializer(object):
    def __init__(self, depth=None, stack=[], **kwargs):
        pass # This __init__ doesn't call super()

class BaseResource(object):
    def __init__(self, view=None, instance=None, depth=None, stack=[], **kwargs):
        # This __init__ from a base class is now skipped during initialization
        super(BaseResource, self).__init__(**kwargs)
        self.view = view
        self.instance = instance

class Resource(Serializer, BaseResource):
    pass

class FormResource(Resource):
    pass

class ModelResource(FormResource):
    model = None
    queryset = None

    def __init__(self, view=None, instance=None, depth=None, stack=[], **kwargs):
        # MRO: ModelResource -> FormResource -> Resource -> Serializer -> BaseResource
        # This super() call resolves to Serializer.__init__, which doesn't delegate up the MRO.
        # As a result, BaseResource.__init__ is never called.
        super(ModelResource, self).__init__(view=None, instance=instance, depth=depth, stack=stack, **kwargs)
        self.model = getattr(view, 'model', None) or self.model

    def get_model(self):
        if self.model is None:
            raise ImproperlyConfigured("Missing model")
        return self.model

    def get_queryset(self):
        queryset = getattr(self, 'queryset', None)
        if queryset is None:
            # This line will fail because self.view was never set in __init__
            queryset = getattr(self.view, 'queryset', None)
            if queryset is None:
                try:
                    model = self.get_model()
                except ImproperlyConfigured:
                    raise ImproperlyConfigured(
                        u"%(cls)s is missing a queryset. Define "
                        u"%(cls)s.model or %(cls)s.queryset." % {'cls': self.__class__}
                    )
                queryset = model._default_manager.all()
        return queryset._clone()

