def format_str(src_contents: str, line_length: int) -> str:
    return src_contents

class NothingChanged(Exception):
    pass

def assert_equivalent(src, dst): pass
def assert_stable(src, dst, line_length): pass

def format_file_contents(
    src_contents: str, line_length: int, fast: bool
) -> str:
    if src_contents.strip() == '':
        raise NothingChanged

    dst_contents = format_str(src_contents, line_length=line_length)
    if src_contents == dst_contents:
        raise NothingChanged

    if not fast:
        assert_equivalent(src_contents, dst_contents)
        assert_stable(src_contents, dst_contents, line_length=line_length)
    return dst_contents

def format_file_in_place(
    src: Path, line_length: int, fast: bool, write_back: bool = False
) -> bool:
    try:
        with tokenize.open(src) as src_buffer:
            src_contents = src_buffer.read()
        contents = format_file_contents(
            src_contents, line_length=line_length, fast=fast
        )
    except NothingChanged:
        return False
    except FileNotFoundError:
        if str(src) == "-":
            raise RuntimeError("CONFIRMED")
        raise

    if write_back:
        with open(src, "w") as f:
            f.write(contents)
    return True

async def schedule_formatting(
    sources: List[Path], line_length: int, check: bool, fast: bool, loop: asyncio.AbstractEventLoop, executor: Executor
) -> int:
    tasks: List[Coroutine] = []
    for source in sources:
        tasks.append(
            loop.run_in_executor(
                executor, format_file_in_place, source, line_length, fast, not check
            )
        )

    return_code = 0
    for task in asyncio.as_completed(tasks):
