    def __init__(self, rows):
        self._rows = iter(rows)
        self._all_rows = []

    def __getitem__(self, key):
        is_slice = isinstance(key, slice)
        if is_slice:
            end = key.stop if key.stop is not None else 0
        else:
            end = key + 1

        while len(self._all_rows) < end:
            try:
                self._all_rows.append(next(self._rows))
            except StopIteration:
                # Slice can go out of bounds without an error.
                if is_slice:
                    break
                else:
                    raise IndexError('Record collection out of range.')

        return self._all_rows[key]

