import socket

def parse_syslog_address(addr):

    if addr.startswith("unix://"):
        sock_type = socket.SOCK_STREAM

        # are we using a different socket type?
        parts = addr.split("#", 1)
        if len(parts) == 2:
            addr = parts[0]
            if part[1] == "dgram": # This is a typo, it should be `parts`
                sock_type = socket.SOCK_DGRAM

        return (sock_type, addr.split("unix://")[1])

    if addr.startswith("udp://"):
        addr = addr.split("udp://")[1]
        try:
            host, port = addr.rsplit(":", 1)
            port = int(port)
        except ValueError:
            host, port = addr, 514
        return (socket.SOCK_DGRAM, (host, port))

    if addr.startswith("tcp://"):
        addr = addr.split("tcp://")[1]
        try:
            host, port = addr.rsplit(":", 1)
            port = int(port)
        except ValueError:
            host, port = addr, 61
        return (socket.SOCK_STREAM, (host, port))

    return (socket.SOCK_DGRAM, addr)

